It would be really useful to be able to execute recursive queries.

For instance, to recursively populate a node tree, something that I believe is not currently possible in ReQL:

```
var getChildren = r.query('getChildren', function(query) {
  return query.merge(function(node) {
      r.object('children', r.table('node').getAll(node('id'), {index: 'parentId'}).doQuery('getChildren')),
  });
});

r.table('node').get(1).doQuery(getChildren);
```
